<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import {getApps,type AppItem}from '../services/content';const props=defineProps<{audience:string}>();const apps=ref<AppItem[]>([]), loading=ref(true);const gender=computed(() => props.audience==='mujeres'?'women':'men');onMounted(async()=>{try{apps.value=await getApps(gender.value)}finally{loading.value=false}})</script>
<template><section class="page-hero"><p class="eyebrow">OPCIONES DISPONIBLES</p><h1>Apps para <em>{{audience}}</em></h1><p>Conoce cómo funciona cada opción antes de tomar una decisión.</p></section><section class="content-section"><div v-if="loading" class="empty-state">Cargando aplicaciones…</div><div v-else-if="apps.length" class="app-grid"><article v-for="app in apps" :key="app.id" class="app-card"><div class="app-art" :style="app.banner_url?{backgroundImage:`url(${app.banner_url})`}:{}"><span>{{app.name.slice(0,1)}}</span></div><div><p>{{app.agency_required?'Trabaja con agencia':'Modalidad independiente'}}</p><h3>{{app.name}}</h3><small>{{app.description||'Detalles disponibles próximamente.'}}</small><button class="text-link">Ver información →</button></div></article></div><div v-else class="empty-state">No hay aplicaciones disponibles actualmente.</div></section></template>

